import json,os,statistics,subprocess,sys
from pathlib import Path
samples={'before':[],'after':[]}
for i in range(5):
 for kind in (['before','after'] if i%2==0 else ['after','before']):
  env=os.environ.copy(); env['PYTHONPATH']='/tmp/docweave-bidi-before' if kind=='before' else '/Users/sheny/Developer/code/Aspose.Words-FOSS-for-Python'
  samples[kind].append(json.loads(subprocess.check_output([sys.executable,'/tmp/docweave-shaping-benchmark.py','whole'],env=env,cwd='/tmp',text=True)))
assert len({s['model_sha256'] for v in samples.values() for s in v})==1
result={'scope':'400 digits, whole run, 5 alternating independent processes; regression check only','samples':samples,'medians':{k:{metric:statistics.median(s[metric] for s in v) for metric in ['seconds','pdf_bytes','rss_bytes']} for k,v in samples.items()}}
Path('/tmp/docweave-bidi-perf.json').write_text(json.dumps(result,indent=2)+'\n')
print(json.dumps(result['medians']))
